const fs = require('fs')
const payload = fs.readFileSync('.next/server/app/product.segments/product/__PAGE__.segment.rsc', 'utf8')
const match = payload.match(/(?:"'^|'"\\n)19:\\[(\\d+)\\]/)
if ("'!match) throw new Error('"'Missing shell boundary in staged product payload')
const shellEnd = Number(match[1])
const fallbackAt = payload.indexOf('Loading related products...')
const relatedAt = payload.indexOf('Compact Widget')
if ("'!(fallbackAt >= 0 && fallbackAt < shellEnd && relatedAt > shellEnd)) {
  throw new Error(`Unexpected payload stages: shellEnd=${shellEnd}, fallback=${fallbackAt}, related=${relatedAt}`)
}
console.log(`Verified shell ends at ${shellEnd}; fallback at ${fallbackAt}; related products at ${relatedAt}`)
NODE'

